210	// Ejecuta las herramientas revalidando permisos en código (RN-07). Una instancia por petición.
211	public class Herramientas(Datos datos, Usuario usuario)
212	{
213	    readonly List<string> ids = [];
214	    public IReadOnlyList<string> IdsConsultados => ids;
215	    public bool UsoDatos { get; private set; }
216	    public bool Denegado { get; private set; }
217	
218	    public string Ejecutar(string nombre, string argumentosJson)
219	    {
220	        switch (nombre)
221	        {
222	            case "consultar_notas": return PorEstudiante(argumentosJson, datos.Notas);
223	            case "consultar_asistencia": return PorEstudiante(argumentosJson, datos.Asistencia);
224	            case "listar_estudiantes_programa":
225	                if (usuario.Rol != "coordinador") return Denegar();
226	                var lista = datos.Estudiantes.Where(e => Permisos.PuedeVerEstudiante(datos, usuario, e.Id)).ToList();
227	                if (lista.Count > 0) Registrar(lista.Select(e => e.Id));
228	                return JsonSerializer.Serialize(lista.Select(e => new { id = e.Id, nombre = e.Nombre, programa = e.Programa }));
229	            default:
230	                return """{"error":"Herramienta desconocida."}""";
231	        }
232	    }
233	
234	    string PorEstudiante(string argumentosJson, IReadOnlyList<JsonElement> fuente)
235	    {
236	        string? id;
237	        try
238	        {
239	            using var doc = JsonDocument.Parse(argumentosJson);
240	            id = doc.RootElement.ValueKind == JsonValueKind.Object
241	                 && doc.RootElement.TryGetProperty("estudianteId", out var v) && v.ValueKind == JsonValueKind.String
242	                ? v.GetString() : null;
243	        }
244	        catch (JsonException) { id = null; }
245	        if (string.IsNullOrEmpty(id)) return """{"error":"Argumentos inválidos: se requiere estudianteId (texto)."}""";
246	
247	        if (!Permisos.PuedeVerEstudiante(datos, usuario, id)) return Denegar();
248	        var registros = fuente.Where(x => x.TryGetProperty("estudianteId", out var e)
249	                                          && e.ValueKind == JsonValueKind.String && e.GetString() == id).ToList();
250	        if (registros.Count > 0) Registrar([id]);
251	        return JsonSerializer.Serialize(registros);
252	    }
253	
254	    string Denegar()
255	    {
256	        Denegado = true;
257	        return """{"error":"Sin permiso."}""";
258	    }
259	
260	    void Registrar(IEnumerable<string> nuevos)
261	    {
262	        UsoDatos = true;
263	        foreach (var i in nuevos) if (!ids.Contains(i)) ids.Add(i);
264	    }
265	}
