35	public record RegistroAuditoria(
36	    string? Rol, string? Id, string? Pregunta,
37	    IReadOnlyList<string> EstudiantesConsultados, IReadOnlyList<Cita> Citas,
38	    int Codigo, int Tokens, double CostoUsd,
39	    string? ModeloPedido = null, IReadOnlyList<string>? ModelosRespondidos = null, long TokensEntrada = 0, long TokensSalida = 0);
40	
41	// Una línea JSON por pregunta. Un fallo al escribir nunca tumba la petición.
42	public class Auditoria(IConfiguration cfg, ILogger<Auditoria> logger)
43	{
44	    const int MaxPregunta = 10_000;
45	    static readonly JsonSerializerOptions Opciones = new()
46	    {
47	        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
48	        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
49	    };
50	
51	    readonly object candado = new();
52	    readonly string ruta = Path.GetFullPath(
53	        string.IsNullOrWhiteSpace(cfg["Auditoria:Ruta"]) ? Path.Combine("logs", "auditoria.jsonl") : cfg["Auditoria:Ruta"]!);
54	
55	    public void Registrar(RegistroAuditoria r)
56	    {
57	        string linea;
58	        try
59	        {
60	            var llave = cfg["LLM_API_KEY"]?.Trim();
61	            string? Limpiar(string? s) =>
62	                s != null && !string.IsNullOrEmpty(llave) ? s.Replace(llave, "[REDACTADO]", StringComparison.Ordinal) : s;
63	
64	            var pregunta = Limpiar(r.Pregunta);
65	            if (pregunta is { Length: > MaxPregunta }) pregunta = pregunta[..MaxPregunta];
66	            linea = JsonSerializer.Serialize(new
67	            {
68	                fechaHora = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture),
69	                rol = Limpiar(r.Rol),
70	                id = Limpiar(r.Id),
71	                pregunta,
72	                estudiantesConsultados = r.EstudiantesConsultados.Select(i => Limpiar(i)).ToList(),
73	                citas = r.Citas.Select(c => new { documento = c.Documento, seccion = c.Seccion }).ToList(),
74	                codigo = r.Codigo,
75	                tokens = r.Tokens,
76	                costoUsd = r.CostoUsd,
77	                modeloPedido = r.ModeloPedido,
78	                modelosRespondidos = (r.ModelosRespondidos ?? []).ToList(),
79	                tokensEntrada = Math.Max(0, r.TokensEntrada),
80	                tokensSalida = Math.Max(0, r.TokensSalida),
81	            }, Opciones);
82	        }
83	        catch (Exception e)
84	        {
85	            logger.LogError("No se pudo construir la línea de auditoría ({Tipo}).", e.GetType().Name);
86	            return;
87	        }
88	
89	        logger.LogInformation("Auditoria {Linea}", linea);
90	        try
91	        {
92	            lock (candado)
93	            {
94	                var dir = Path.GetDirectoryName(ruta);
95	                if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
96	                File.AppendAllText(ruta, linea + "\n");
97	            }
98	        }
99	        catch (Exception e)
100	        {
101	            logger.LogError("No se pudo escribir la auditoría ({Tipo}).", e.GetType().Name);
102	        }
103	    }
104	}
