1	using System.Text.Json;
2	using System.Text.Json.Nodes;
3	
4	namespace TutorFlow.Api.Llm;
5	
6	public class OpenAiCompatClient(IHttpClientFactory fabrica, IConfiguration cfg) : ILlmClient
7	{
8	    public const string BaseDefecto = "https://generativelanguage.googleapis.com/v1beta/openai";
9	    // gemini-2.5-flash ya no está disponible para cuentas nuevas; gemini-3.5-flash comprobado con la API real.
10	    public const string ModeloDefecto = "gemini-3.5-flash";
11	    // Los modelos Gemini 3 gastan tokens de razonamiento antes de responder; con 2048 puede quedar sin texto visible.
12	    const int MaxTokens = 8192;
13	
14	    public string? ModeloEfectivo() => string.IsNullOrWhiteSpace(cfg["LLM_MODEL"]) ? ModeloDefecto : cfg["LLM_MODEL"]!.Trim();
15	
16	    public async Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
17	        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
18	    {
19	        var baseUrl = (string.IsNullOrWhiteSpace(cfg["LLM_BASE_URL"]) ? BaseDefecto : cfg["LLM_BASE_URL"]!).TrimEnd('/');
20	        var modelo = ModeloEfectivo()!;
21	
22	        var msgs = new JsonArray { new JsonObject { ["role"] = "system", ["content"] = sistema } };
23	        foreach (var m in mensajes)
24	        {
25	            if (m.Rol == "tool")
26	                msgs.Add(new JsonObject { ["role"] = "tool", ["tool_call_id"] = m.ToolCallId, ["content"] = m.Contenido });
27	            else if (m.Rol == "assistant" && m.Llamadas is { Count: > 0 })
28	            {
29	                var calls = new JsonArray();
30	                foreach (var l in m.Llamadas)
31	                {
32	                    var call = new JsonObject
33	                    {
34	                        ["id"] = l.Id,
35	                        ["type"] = "function",
36	                        ["function"] = new JsonObject { ["name"] = l.Nombre, ["arguments"] = l.ArgumentosJson },
37	                    };
38	                    // Gemini exige reenviar extra_content (thought_signature) tal cual lo emitió.
39	                    if (!string.IsNullOrEmpty(l.ExtraJson))
40	                        call["extra_content"] = JsonNode.Parse(l.ExtraJson);
41	                    calls.Add(call);
42	                }
43	                msgs.Add(new JsonObject
44	                {
45	                    ["role"] = "assistant",
46	                    ["content"] = string.IsNullOrEmpty(m.Contenido) ? null : m.Contenido,
47	                    ["tool_calls"] = calls,
48	                });
49	            }
50	            else
51	                msgs.Add(new JsonObject { ["role"] = m.Rol, ["content"] = m.Contenido });
52	        }
53	
54	        var cuerpo = new JsonObject { ["model"] = modelo, ["messages"] = msgs, ["max_tokens"] = MaxTokens };
55	        if (herramientas.Count > 0)
56	        {
57	            var tools = new JsonArray();
58	            foreach (var h in herramientas)
59	                tools.Add(new JsonObject
60	                {
61	                    ["type"] = "function",
62	                    ["function"] = new JsonObject
63	                    {
64	                        ["name"] = h.Nombre,
65	                        ["description"] = h.Descripcion,
66	                        ["parameters"] = LlmHttp.ParseOVacio(h.ParametrosJsonSchema),
67	                    },
68	                });
69	            cuerpo["tools"] = tools;
70	        }
71	
72	        using var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/chat/completions");
73	        req.Headers.TryAddWithoutValidation("Authorization", "Bearer " + cfg["LLM_API_KEY"]?.Trim());
74	        using var doc = await LlmHttp.EnviarAsync(fabrica.CreateClient("llm"), req, cuerpo, ct);
75	
76	        try
77	        {
78	            var raiz = doc.RootElement;
79	            var mensaje = raiz.GetProperty("choices")[0].GetProperty("message");
80	            string? texto = mensaje.TryGetProperty("content", out var c) && c.ValueKind == JsonValueKind.String ? c.GetString() : null;
81	            var llamadas = new List<LlmLlamadaHerramienta>();
82	            if (mensaje.TryGetProperty("tool_calls", out var tc) && tc.ValueKind == JsonValueKind.Array)
83	            {
84	                var n = 0;
85	                foreach (var t in tc.EnumerateArray())
86	                {
87	                    var f = t.GetProperty("function");
88	                    var id = t.TryGetProperty("id", out var i) && i.ValueKind == JsonValueKind.String && !string.IsNullOrEmpty(i.GetString())
89	                        ? i.GetString()! : $"call_{n}";
90	                    var args = f.TryGetProperty("arguments", out var a)
91	                        ? (a.ValueKind == JsonValueKind.String ? a.GetString()! : a.GetRawText()) : "{}";
92	                    // Solo un objeto JSON se guarda y reenvía; otro tipo se descarta. Tampoco se guarda uno de más de 8 KB:
93	                    // se reenvía en cada vuelta, así que un proveedor hostil podría inflar tokens y memoria.
94	                    var extra = t.TryGetProperty("extra_content", out var ex) && ex.ValueKind == JsonValueKind.Object
95	                        ? ex.GetRawText() : null;
96	                    if (extra is not null && extra.Length > 8 * 1024) extra = null;
97	                    llamadas.Add(new(id, f.GetProperty("name").GetString()!, string.IsNullOrWhiteSpace(args) ? "{}" : args, extra));
98	                    n++;
99	                }
100	            }
101	            var uso = raiz.TryGetProperty("usage", out var u) ? u : default;
102	            var entrada = LlmHttp.Entero(uso, "prompt_tokens");
103	            var completion = LlmHttp.Entero(uso, "completion_tokens");
104	            // Gemini 3 reporta los tokens de razonamiento solo en total_tokens (completion_tokens no los incluye)
105	            // y los cobra como salida. Por eso la salida es max(completion, total - prompt); nunca baja de completion
106	            // y no se suma reasoning_tokens aparte para no contarlos dos veces. Si total falta o es inválido, vale 0.
107	            var restante = (long)LlmHttp.Entero(uso, "total_tokens") - entrada;
108	            var salida = (int)Math.Max(completion, Math.Min(restante, int.MaxValue));
109	            return new(texto, llamadas, new(entrada, salida),
110	                raiz.TryGetProperty("model", out var mo) && mo.ValueKind == JsonValueKind.String ? mo.GetString() : null);
111	        }
112	        catch (Exception e) when (e is KeyNotFoundException or InvalidOperationException or IndexOutOfRangeException or ArgumentOutOfRangeException)
113	        {
114	            throw new LlmException("El proveedor del modelo devolvió una respuesta sin los campos esperados.");
115	        }
116	    }
117	}
