52	        {
53	            ["model"] = modelo,
54	            ["max_tokens"] = MaxTokens,
55	            ["system"] = new JsonArray
56	            {
57	                new JsonObject
58	                {
59	                    ["type"] = "text",
60	                    ["text"] = sistema,
61	                    ["cache_control"] = new JsonObject { ["type"] = "ephemeral" },
62	                },
63	            },
64	            ["messages"] = msgs,
65	        };
66	        if (herramientas.Count > 0)
67	        {
68	            var tools = new JsonArray();
69	            foreach (var h in herramientas)
70	                tools.Add(new JsonObject
71	                {
72	                    ["name"] = h.Nombre,
73	                    ["description"] = h.Descripcion,
74	                    ["input_schema"] = LlmHttp.ParseOVacio(h.ParametrosJsonSchema),
75	                });
76	            cuerpo["tools"] = tools;
77	        }
78	
79	        using var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/v1/messages");
80	        req.Headers.TryAddWithoutValidation("x-api-key", cfg["LLM_API_KEY"]?.Trim());
81	        req.Headers.TryAddWithoutValidation("anthropic-version", "2023-06-01");
82	        using var doc = await LlmHttp.EnviarAsync(fabrica.CreateClient("llm"), req, cuerpo, ct);
83	
84	        try
85	        {
86	            var raiz = doc.RootElement;
87	            var texto = new StringBuilder();
88	            var llamadas = new List<LlmLlamadaHerramienta>();
89	            foreach (var b in raiz.GetProperty("content").EnumerateArray())
90	            {
91	                var tipo = b.GetProperty("type").GetString();
92	                if (tipo == "text" && b.TryGetProperty("text", out var t) && t.ValueKind == JsonValueKind.String)
93	                    texto.Append(t.GetString());
94	                else if (tipo == "tool_use")
95	                    llamadas.Add(new(b.GetProperty("id").GetString()!, b.GetProperty("name").GetString()!,
96	                        b.TryGetProperty("input", out var inp) ? inp.GetRawText() : "{}"));
97	            }
98	            var uso = raiz.TryGetProperty("usage", out var u) ? u : default;
99	            var entrada = LlmHttp.Entero(uso, "input_tokens") + LlmHttp.Entero(uso, "cache_creation_input_tokens")
100	                          + LlmHttp.Entero(uso, "cache_read_input_tokens");
101	            return new(texto.Length > 0 ? texto.ToString() : null, llamadas, new(entrada, LlmHttp.Entero(uso, "output_tokens")),
102	                raiz.TryGetProperty("model", out var mo) && mo.ValueKind == JsonValueKind.String ? mo.GetString() : null);
103	        }
104	        catch (Exception e) when (e is KeyNotFoundException or InvalidOperationException)
105	        {
106	            throw new LlmException("El proveedor del modelo devolvió una respuesta sin los campos esperados.");
107	        }
108	    }
109	}
