87	/// <summary>Datos de referencia leídos de /data: índice de citas y personas. Nada va escrito en código.</summary>
88	public sealed class Corpus
89	{
90	    public HashSet<(string Documento, string Seccion)> Citas { get; } = new();
91	    public List<Persona> Estudiantes { get; } = new();
92	    public List<Persona> Coordinadores { get; } = new();
93	
94	    public static Corpus Cargar(string dataDir)
95	    {
96	        var c = new Corpus();
97	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "reglamento"), "*.md"))
98	        {
99	            var doc = Path.GetFileName(f);
100	            foreach (var l in File.ReadLines(f))
101	            {
102	                if (l.StartsWith("## ", StringComparison.Ordinal))
103	                    c.Citas.Add((doc, l[3..].Trim()));
104	            }
105	        }
106	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "api"), "*.json"))
107	        {
108	            using var d = JsonDocument.Parse(File.ReadAllText(f));
109	            if (d.RootElement.ValueKind != JsonValueKind.Array) continue;
110	            var delArchivo = new List<(Persona P, bool ConSemestre)>();
111	            foreach (var e in d.RootElement.EnumerateArray())
112	            {
113	                if (e.ValueKind != JsonValueKind.Object) continue;
114	                if (!e.TryGetProperty("id", out var id) || !e.TryGetProperty("nombre", out var nom)
115	                    || !e.TryGetProperty("programa", out var prog)) continue;
116	                var p = new Persona(id.GetString() ?? "", nom.GetString() ?? "", prog.GetString() ?? "");
117	                // Los estudiantes se distinguen de los coordinadores por tener semestre.
118	                delArchivo.Add((p, e.TryGetProperty("semestre", out _)));
119	            }
120	            // Falla cerrada (igual que RN-14 en Datos.cs): la forma es una decisión por archivo.
121	            if (delArchivo.Count > 0 && delArchivo.Any(x => x.ConSemestre != delArchivo[0].ConSemestre))
122	                throw new InvalidDataException($"El archivo '{Path.GetFileName(f)}' mezcla usuarios con y sin 'semestre'; no se puede clasificar estudiantes y coordinadores.");
123	            foreach (var (p, conSemestre) in delArchivo)
124	                (conSemestre ? c.Estudiantes : c.Coordinadores).Add(p);
125	        }
126	        var repetidos = c.Estudiantes.Select(x => x.Id).Intersect(c.Coordinadores.Select(x => x.Id)).ToList();
127	        if (repetidos.Count > 0)
128	            throw new InvalidDataException($"Ids presentes como estudiante y coordinador: {string.Join(", ", repetidos)}.");
129	        if (c.Estudiantes.Count == 0 || c.Coordinadores.Count == 0)
130	            throw new InvalidDataException("No se encontraron estudiantes y coordinadores en los datos; la regla R2 no se puede comprobar.");
131	        return c;
132	    }
133	
134	    /// <summary>Estudiantes que el usuario NO puede ver.</summary>
135	    public IEnumerable<Persona> Prohibidos(UsuarioCaso u)
136	    {
137	        if (u.Rol == "estudiante") return Estudiantes.Where(e => e.Id != u.Id);
138	        if (u.Rol == "coordinador")
139	        {
140	            var prog = Coordinadores.FirstOrDefault(x => x.Id == u.Id)?.Programa;
141	            return Estudiantes.Where(e => e.Programa != prog);
142	        }
143	        return Estudiantes;
144	    }
145	}
