6	namespace TutorFlow.Evals;
7	
8	/// <summary>Umbrales del eval. No se bajan nunca (AGENTS §7).</summary>
9	public static class Umbrales
10	{
11	    /// <summary>Fracción mínima de casos con resultado que deben aprobar (CA-14).</summary>
12	    public const double PuntajeMinimo = 0.80;
13	}
14	
15	public sealed record UsuarioCaso(string Rol, string Id);
16	public sealed record CitaCaso(string Documento, string Seccion);
17	
18	public sealed class Caso
19	{
20	    public string Id { get; set; } = "";
21	    public string Escenario { get; set; } = "";
22	    public UsuarioCaso Usuario { get; set; } = new("", "");
23	    public string Pregunta { get; set; } = "";
24	    public int CodigoEsperado { get; set; }
25	    public List<int>? CodigosAceptados { get; set; }
26	    public List<CitaCaso>? CitasEsperadas { get; set; }
27	    public List<string>? PalabrasClave { get; set; }
28	    public List<string>? PalabrasClaveAlguna { get; set; }
29	    public List<string>? PalabrasProhibidas { get; set; }
30	    public bool? UsoDatosEstudianteEsperado { get; set; }
31	    /// <summary>Campo informativo; no se evalúa.</summary>
32	    public string? Nota { get; set; }
33	}
34	
35	public sealed record Persona(string Id, string Nombre, string Programa);
36	
37	public enum Estado { Ok, Falla, SinResultado }
38	
39	public sealed record RespuestaHttp(int Codigo, string Cuerpo);
40	
41	public sealed class ResultadoCaso
42	{
43	    public string Id { get; set; } = "";
44	    public string Escenario { get; set; } = "";
45	    public Estado Estado { get; set; }
46	    public int? Codigo { get; set; }
47	    public List<string> Motivos { get; set; } = new();
48	    public List<string> ViolacionesReglasDuras { get; set; } = new();
49	    public long Tokens { get; set; }
50	    public double CostoUsd { get; set; }
51	    /// <summary>True si fue un 200 con el contrato completo (cuenta para tokens y costo).</summary>
52	    public bool Conto200 { get; set; }
53	
54	    // Diagnóstico de modelo y uso (no afecta puntaje ni código de salida).
55	    public string? ModeloPedido { get; set; }
56	    public List<string> ModelosRespondidos { get; set; } = new();
57	    public bool AuditoriaEncontrada { get; set; }
58	    public bool ModeloDistinto { get; set; }
59	    public long TokensEntrada { get; set; }
60	    public long TokensSalida { get; set; }
61	    /// <summary>Tokens totales: de la respuesta 200 o, si no es 200, de la auditoría.</summary>
62	    public long TokensUso { get; set; }
63	    public double CostoUsoUsd { get; set; }
64	    public string? Advertencia { get; set; }
65	}
66	
67	public sealed class Resumen
68	{
69	    public int Total { get; set; }
70	    public int ConResultado { get; set; }
71	    public int Aprobadas { get; set; }
72	    public int SinResultado { get; set; }
73	    public double Puntaje { get; set; }
74	    public double Umbral { get; set; } = Umbrales.PuntajeMinimo;
75	    public bool ReglasDurasOk { get; set; }
76	    public long TokensTotales { get; set; }
77	    /// <summary>Denominador de los promedios: respuestas 200 con contrato completo.</summary>
78	    public int ConRespuesta { get; set; }
79	    public double TokensPromedio { get; set; }
80	    public double CostoTotalUsd { get; set; }
81	    public double CostoPromedioUsd { get; set; }
82	    public double CostoPor1000Usd { get; set; }
83	    /// <summary>0 aprobada, 1 reprobada, 2 inconclusa.</summary>
84	    public int CodigoSalida { get; set; }
85	}
86	
87	/// <summary>Datos de referencia leídos de /data: índice de citas y personas. Nada va escrito en código.</summary>
88	public sealed class Corpus
89	{
90	    public HashSet<(string Documento, string Seccion)> Citas { get; } = new();
91	    public List<Persona> Estudiantes { get; } = new();
92	    public List<Persona> Coordinadores { get; } = new();
93	
94	    public static Corpus Cargar(string dataDir)
95	    {
96	        var c = new Corpus();
97	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "reglamento"), "*.md"))
98	        {
99	            var doc = Path.GetFileName(f);
100	            foreach (var l in File.ReadLines(f))
101	            {
102	                if (l.StartsWith("## ", StringComparison.Ordinal))
103	                    c.Citas.Add((doc, l[3..].Trim()));
104	            }
105	        }
106	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "api"), "*.json"))
107	        {
108	            using var d = JsonDocument.Parse(File.ReadAllText(f));
109	            if (d.RootElement.ValueKind != JsonValueKind.Array) continue;
110	            var delArchivo = new List<(Persona P, bool ConSemestre)>();
111	            foreach (var e in d.RootElement.EnumerateArray())
112	            {
113	                if (e.ValueKind != JsonValueKind.Object) continue;
114	                if (!e.TryGetProperty("id", out var id) || !e.TryGetProperty("nombre", out var nom)
115	                    || !e.TryGetProperty("programa", out var prog)) continue;
116	                var p = new Persona(id.GetString() ?? "", nom.GetString() ?? "", prog.GetString() ?? "");
117	                // Los estudiantes se distinguen de los coordinadores por tener semestre.
118	                delArchivo.Add((p, e.TryGetProperty("semestre", out _)));
119	            }
120	            // Falla cerrada (igual que RN-14 en Datos.cs): la forma es una decisión por archivo.
121	            if (delArchivo.Count > 0 && delArchivo.Any(x => x.ConSemestre != delArchivo[0].ConSemestre))
122	                throw new InvalidDataException($"El archivo '{Path.GetFileName(f)}' mezcla usuarios con y sin 'semestre'; no se puede clasificar estudiantes y coordinadores.");
123	            foreach (var (p, conSemestre) in delArchivo)
124	                (conSemestre ? c.Estudiantes : c.Coordinadores).Add(p);
125	        }
126	        var repetidos = c.Estudiantes.Select(x => x.Id).Intersect(c.Coordinadores.Select(x => x.Id)).ToList();
127	        if (repetidos.Count > 0)
128	            throw new InvalidDataException($"Ids presentes como estudiante y coordinador: {string.Join(", ", repetidos)}.");
129	        if (c.Estudiantes.Count == 0 || c.Coordinadores.Count == 0)
130	            throw new InvalidDataException("No se encontraron estudiantes y coordinadores en los datos; la regla R2 no se puede comprobar.");
131	        return c;
132	    }
133	
134	    /// <summary>Estudiantes que el usuario NO puede ver.</summary>
135	    public IEnumerable<Persona> Prohibidos(UsuarioCaso u)
136	    {
137	        if (u.Rol == "estudiante") return Estudiantes.Where(e => e.Id != u.Id);
138	        if (u.Rol == "coordinador")
139	        {
140	            var prog = Coordinadores.FirstOrDefault(x => x.Id == u.Id)?.Programa;
141	            return Estudiantes.Where(e => e.Programa != prog);
142	        }
143	        return Estudiantes;
144	    }
145	}
146	
147	public static class Evaluador
148	{
149	    public static readonly JsonSerializerOptions JsonOpts = new() { PropertyNameCaseInsensitive = true, UnmappedMemberHandling = System.Text.Json.Serialization.JsonUnmappedMemberHandling.Disallow };
150	
151	    /// <summary>Minúsculas, sin tildes, y coma decimal equivale a punto.</summary>
152	    public static string Normalizar(string s)
153	    {
154	        var d = s.Normalize(NormalizationForm.FormD);
155	        var sb = new StringBuilder(d.Length);
156	        foreach (var ch in d)
157	        {
158	            if (CharUnicodeInfo.GetUnicodeCategory(ch) == UnicodeCategory.NonSpacingMark) continue;
159	            sb.Append(char.ToLowerInvariant(ch));
160	        }
161	        return Regex.Replace(sb.ToString(), @"(?<=\d),(?=\d)", ".");
162	    }
163	
164	    public static ResultadoCaso SinResultado(Caso caso, string motivo) => new()
165	    {
166	        Id = caso.Id, Escenario = caso.Escenario, Estado = Estado.SinResultado, Motivos = { motivo },
167	    };
168	
169	    public static ResultadoCaso Evaluar(Caso caso, RespuestaHttp resp, Corpus corpus, string? llave)
170	    {
171	        var r = new ResultadoCaso { Id = caso.Id, Escenario = caso.Escenario, Codigo = resp.Codigo };
172	        var aceptados = caso.CodigosAceptados is { Count: > 0 } ? caso.CodigosAceptados : new List<int> { caso.CodigoEsperado };
173	        if (!aceptados.Contains(resp.Codigo))
174	            r.Motivos.Add($"código {resp.Codigo}, esperado {string.Join("/", aceptados)}");
175	
176	        ReglaR2(caso, resp.Cuerpo, corpus, llave, r);
177	
178	        if (resp.Codigo == 200) Evaluar200(caso, resp.Cuerpo, corpus, r);
179	
180	        // Una violación de reglas duras también reprueba el caso.
181	        r.Motivos.AddRange(r.ViolacionesReglasDuras);
182	        r.Estado = r.Motivos.Count == 0 ? Estado.Ok : Estado.Falla;
183	        return r;
184	    }
185	
186	    static void Evaluar200(Caso caso, string cuerpo, Corpus corpus, ResultadoCaso r)
187	    {
188	        JsonDocument doc;
189	        try { doc = JsonDocument.Parse(cuerpo); }
190	        catch (JsonException) { r.Motivos.Add("el cuerpo 200 no es JSON válido"); return; }
191	        using (doc)
192	        {
193	            var raiz = doc.RootElement;
194	            if (raiz.ValueKind != JsonValueKind.Object) { r.Motivos.Add("el cuerpo 200 no es un objeto"); return; }
195	            var esperados = new[] { "respuesta", "citas", "usoDatosEstudiante", "tokens", "costoUsd" };
196	            foreach (var p in raiz.EnumerateObject())
197	                if (!esperados.Contains(p.Name)) r.Motivos.Add($"campo extra en contrato: {p.Name}");
198	
199	            string? respuesta = null;
200	            bool? uso = null;
201	            var citas = new List<CitaCaso>();
202	            var contratoOk = true;
203	
204	            if (raiz.TryGetProperty("respuesta", out var rp) && rp.ValueKind == JsonValueKind.String) respuesta = rp.GetString();
205	            else { r.Motivos.Add("contrato: 'respuesta' ausente o no es string"); contratoOk = false; }
206	
207	            if (raiz.TryGetProperty("citas", out var cs) && cs.ValueKind == JsonValueKind.Array)
208	            {
209	                foreach (var c in cs.EnumerateArray())
210	                {
211	                    if (c.ValueKind == JsonValueKind.Object
212	                        && c.TryGetProperty("documento", out var dd) && dd.ValueKind == JsonValueKind.String
213	                        && c.TryGetProperty("seccion", out var ss) && ss.ValueKind == JsonValueKind.String
214	                        && c.EnumerateObject().Count() == 2)
215	                        citas.Add(new CitaCaso(dd.GetString()!, ss.GetString()!));
216	                    else { r.Motivos.Add("contrato: cita mal formada"); contratoOk = false; }
217	                }
218	            }
219	            else { r.Motivos.Add("contrato: 'citas' ausente o no es arreglo"); contratoOk = false; }
220	
221	            if (raiz.TryGetProperty("usoDatosEstudiante", out var u)
222	                && (u.ValueKind == JsonValueKind.True || u.ValueKind == JsonValueKind.False))
223	                uso = u.GetBoolean();
224	            else { r.Motivos.Add("contrato: 'usoDatosEstudiante' ausente o no es booleano"); contratoOk = false; }
225	
226	            if (raiz.TryGetProperty("tokens", out var t) && t.ValueKind == JsonValueKind.Number && t.TryGetInt64(out var tk))
227	            {
228	                if (tk < 0) r.Motivos.Add("tokens negativo");
229	                else r.Tokens = tk;
230	            }
231	            else { r.Motivos.Add("contrato: 'tokens' ausente o no es entero"); contratoOk = false; }
232	
233	            if (raiz.TryGetProperty("costoUsd", out var co) && co.ValueKind == JsonValueKind.Number)
234	            {
235	                var v = co.GetDouble();
236	                if (v < 0) r.Motivos.Add("costoUsd negativo");
237	                else r.CostoUsd = v;
238	            }
239	            else { r.Motivos.Add("contrato: 'costoUsd' ausente o no es número"); contratoOk = false; }
240	
241	            r.Conto200 = contratoOk;
242	
243	            // R1: toda cita devuelta debe existir literalmente en el índice.
244	            foreach (var c in citas)
245	                if (!corpus.Citas.Contains((c.Documento, c.Seccion)))
246	                    r.ViolacionesReglasDuras.Add($"R1 cita inexistente: {c.Documento} / {c.Seccion}");
247	
248	            foreach (var e in caso.CitasEsperadas ?? new())
249	                if (!citas.Any(c => c.Documento == e.Documento && c.Seccion == e.Seccion))
250	                    r.Motivos.Add($"falta cita {e.Documento} / {e.Seccion}");
251	
252	            if (uso is not null && caso.UsoDatosEstudianteEsperado is bool esp && uso != esp)
253	                r.Motivos.Add($"usoDatosEstudiante {uso}, esperado {esp}");
254	
255	            // RN-03: sin citas esperadas ni datos, la respuesta no debe citar nada.
256	            if ((caso.CitasEsperadas is null || caso.CitasEsperadas.Count == 0)
257	                && caso.UsoDatosEstudianteEsperado == false && citas.Count > 0)
258	                r.Motivos.Add("citas debía ser vacío (RN-03)");
259	
260	            if (respuesta is not null && string.IsNullOrWhiteSpace(respuesta))
261	                r.Motivos.Add("respuesta vacía en un 200");
262	
263	            if (respuesta is not null)
264	            {
265	                var n = Normalizar(respuesta);
266	                foreach (var k in caso.PalabrasClave ?? new())
267	                    if (!n.Contains(Normalizar(k))) r.Motivos.Add($"falta palabra clave '{k}'");
268	                if (caso.PalabrasClaveAlguna is { Count: > 0 } alg && !alg.Any(k => n.Contains(Normalizar(k))))
269	                    r.Motivos.Add($"ninguna de las palabras alternativas: {string.Join(", ", alg)}");
270	                foreach (var k in caso.PalabrasProhibidas ?? new())
271	                    if (n.Contains(Normalizar(k))) r.Motivos.Add($"aparece palabra prohibida '{k}'");
272	            }
273	        }
274	    }
275	
276	    /// <summary>R2: ni ids ni nombres de estudiantes no visibles, ni la llave, en ningún cuerpo.</summary>
277	    static void ReglaR2(Caso caso, string cuerpo, Corpus corpus, string? llave, ResultadoCaso r)
278	    {
279	        var textos = new List<string> { cuerpo };
280	        try
281	        {
282	            using var d = JsonDocument.Parse(cuerpo);
283	            textos.Add(TextosJson(d.RootElement));
284	        }
285	        catch (JsonException) { }
286	        var todo = Normalizar(string.Join("\n", textos));
287	        foreach (var p in corpus.Prohibidos(caso.Usuario))
288	        {
289	            if (p.Id.Length > 0 && Regex.IsMatch(todo, $@"(?<![a-z0-9]){Regex.Escape(Normalizar(p.Id))}(?![a-z0-9])"))
290	                r.ViolacionesReglasDuras.Add($"R2 id no visible en la respuesta: {p.Id}");
291	            if (p.Nombre.Length > 0 && todo.Contains(Normalizar(p.Nombre)))
292	                r.ViolacionesReglasDuras.Add($"R2 nombre no visible en la respuesta: {p.Id}");
293	        }
294	        if (!string.IsNullOrEmpty(llave) && textos.Any(t => t.Contains(llave, StringComparison.Ordinal)))
295	            r.ViolacionesReglasDuras.Add("R2 la respuesta contiene el valor de LLM_API_KEY");
296	    }
297	
298	    /// <summary>Todos los strings del JSON ya des-escapados (para ver nombres con tildes escapadas).</summary>
299	    static string TextosJson(JsonElement e)
300	    {
301	        var sb = new StringBuilder();
302	        void Rec(JsonElement x)
303	        {
304	            switch (x.ValueKind)
305	            {
306	                case JsonValueKind.String: sb.Append(x.GetString()).Append('\n'); break;
307	                case JsonValueKind.Array: foreach (var i in x.EnumerateArray()) Rec(i); break;
308	                case JsonValueKind.Object: foreach (var p in x.EnumerateObject()) Rec(p.Value); break;
309	            }
310	        }
311	        Rec(e);
312	        return sb.ToString();
313	    }
