43	/// <summary>Lectura de la auditoría de la API para saber qué modelo respondió. Solo diagnóstico.</summary>
44	public static class UsoModelo
45	{
46	    public static long Longitud(string ruta)
47	    {
48	        try { return File.Exists(ruta) ? new FileInfo(ruta).Length : 0; }
49	        catch (IOException) { return 0; }
50	    }
51	
52	    public static string QuitarPrefijo(string m) => m.StartsWith("models/", StringComparison.OrdinalIgnoreCase) ? m[7..] : m;
53	
54	    /// <summary>Última línea nueva (desde el byte <paramref name="desde"/>) cuya pregunta e id coinciden.</summary>
55	    public static LineaAuditoria? Buscar(string ruta, long desde, string pregunta, string id)
56	    {
57	        try
58	        {
59	            if (!File.Exists(ruta)) return null;
60	            string texto;
61	            using (var fs = new FileStream(ruta, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
62	            {
63	                if (desde > fs.Length) desde = 0; // el archivo se rotó
64	                fs.Seek(desde, SeekOrigin.Begin);
65	                using var sr = new StreamReader(fs, Encoding.UTF8);
66	                texto = sr.ReadToEnd();
67	            }
68	            LineaAuditoria? res = null;
69	            foreach (var l in texto.Split('\n', StringSplitOptions.RemoveEmptyEntries))
70	            {
71	                try
72	                {
73	                    using var d = JsonDocument.Parse(l);
74	                    var r = d.RootElement;
75	                    if (r.ValueKind != JsonValueKind.Object) continue;
76	                    if (Str(r, "pregunta") != pregunta || Str(r, "id") != id) continue;
77	                    var modelos = new List<string>();
78	                    if (r.TryGetProperty("modelosRespondidos", out var mr) && mr.ValueKind == JsonValueKind.Array)
79	                        foreach (var m in mr.EnumerateArray())
80	                            if (m.ValueKind == JsonValueKind.String && m.GetString() is { Length: > 0 } s) modelos.Add(s);
81	                    res = new LineaAuditoria(Str(r, "modeloPedido"), modelos, Num(r, "tokensEntrada"), Num(r, "tokensSalida"),
82	                        Num(r, "tokens"), r.TryGetProperty("costoUsd", out var c) && c.ValueKind == JsonValueKind.Number ? c.GetDouble() : 0,
83	                        (int)Num(r, "codigo"));
84	                }
85	                catch (JsonException) { }
86	            }
87	            return res;
88	        }
89	        catch (IOException) { return null; }
90	        catch (UnauthorizedAccessException) { return null; }
91	    }
92	
93	    static string? Str(JsonElement e, string n) => e.TryGetProperty(n, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;
94	    static long Num(JsonElement e, string n) => e.TryGetProperty(n, out var v) && v.ValueKind == JsonValueKind.Number && v.TryGetInt64(out var l) ? l : 0;
95	
96	    /// <summary>Completa el resultado con lo que dice la auditoría (o la respuesta 200 para tokens y costo).</summary>
97	    public static void Aplicar(ResultadoCaso r, LineaAuditoria? a)
98	    {
99	        r.AuditoriaEncontrada = a != null;
100	        if (a != null)
101	        {
102	            r.ModeloPedido = a.ModeloPedido;
103	            r.ModelosRespondidos = a.ModelosRespondidos;
104	            r.TokensEntrada = a.TokensEntrada;
105	            r.TokensSalida = a.TokensSalida;
106	        }
107	        else r.Advertencia = "auditoría no disponible: modelo desconocido";
108	
109	        if (r.Conto200) { r.TokensUso = r.Tokens; r.CostoUsoUsd = r.CostoUsd; }
110	        else if (a != null) { r.TokensUso = a.Tokens; r.CostoUsoUsd = a.CostoUsd; }
111	
112	        if (r.ModeloPedido is { Length: > 0 } p)
113	        {
114	            var pedido = QuitarPrefijo(p);
115	            r.ModeloDistinto = r.ModelosRespondidos.Any(m => !string.Equals(QuitarPrefijo(m), pedido, StringComparison.OrdinalIgnoreCase));
116	        }
117	    }
