119	    public static ResumenModelo Resumir(IReadOnlyList<ResultadoCaso> rs, string? pedidoEnv, string? precioEntrada, string? precioSalida)
120	    {
121	        var s = new ResumenModelo { Preguntas = rs.Count };
122	        s.ModeloPedido = rs.Select(x => x.ModeloPedido).FirstOrDefault(m => !string.IsNullOrEmpty(m)) ?? pedidoEnv;
123	        foreach (var r in rs)
124	        {
125	            if (!r.AuditoriaEncontrada) s.SinAuditoria++;
126	            if (r.ModeloDistinto) s.ModeloDistinto++;
127	            foreach (var m in r.ModelosRespondidos.Distinct())
128	                s.ModelosRespondidos[m] = s.ModelosRespondidos.GetValueOrDefault(m) + 1;
129	        }
130	        s.Rechazadas403 = Grupo(rs.Where(x => x.Codigo == 403).ToList());
131	        s.Resto = Grupo(rs.Where(x => x.Codigo != 403).ToList());
132	        if (!string.IsNullOrWhiteSpace(precioEntrada)) s.PrecioEntradaMtok = precioEntrada.Trim();
133	        if (!string.IsNullOrWhiteSpace(precioSalida)) s.PrecioSalidaMtok = precioSalida.Trim();
134	        return s;
135	    }
136	
137	    static GrupoUso Grupo(List<ResultadoCaso> rs)
138	    {
139	        var g = new GrupoUso { Preguntas = rs.Count };
140	        g.TokensEntrada = rs.Sum(x => x.TokensEntrada);
141	        g.TokensSalida = rs.Sum(x => x.TokensSalida);
142	        g.Tokens = rs.Sum(x => x.TokensUso);
143	        g.CostoTotalUsd = rs.Sum(x => x.CostoUsoUsd);
144	        g.SinResultado = rs.Count(x => x.Estado == Estado.SinResultado);
145	        // Denominador: solo las que obtuvieron respuesta del modelo; las SIN RESULTADO (0 tokens) subestimarían el promedio.
146	        g.ConRespuesta = rs.Count(x => x.Estado != Estado.SinResultado && (x.TokensUso > 0 || x.Codigo == 200));
147	        var sin = rs.Where(x => x.Estado == Estado.SinResultado).ToList();
148	        g.TokensSinResultado = sin.Sum(x => x.TokensUso);
149	        g.CostoSinResultadoUsd = sin.Sum(x => x.CostoUsoUsd);
150	        if (g.ConRespuesta > 0)
151	        {
152	            // Numerador y denominador sobre el mismo conjunto: las preguntas con respuesta del modelo.
153	            g.TokensPromedio = (double)(g.Tokens - g.TokensSinResultado) / g.ConRespuesta;
154	            g.CostoPor1000Usd = (g.CostoTotalUsd - g.CostoSinResultadoUsd) / g.ConRespuesta * 1000;
155	        }
156	        g.ConTokens = rs.Where(x => x.TokensUso > 0).Select(x => x.Id).ToList();
157	        return g;
158	    }
159	}
