            ["LLM_RESPALDO_2_PRECIO_ENTRADA_MTOK"] = "2", ["LLM_RESPALDO_2_PRECIO_SALIDA_MTOK"] = "4",
        };
        using var e = new EntornoAuditoria(null, cfg);
        e.Proveedor.Responde(HttpStatusCode.TooManyRequests, "x").Ok(Ok);
        var (c, b) = await e.Preguntar("hola", "estudiante", "T-E1");
        Assert.Equal(HttpStatusCode.OK, c);
        Assert.Contains("\"costoUsd\":6", b);
        var l = await e.UnaLinea();
        Assert.Equal("respaldo-2", l.GetProperty("proveedor").GetString());
        Assert.Equal(2, l.GetProperty("intentos").GetArrayLength());
        Assert.Contains("429", l.GetProperty("intentos").ToString());
        Assert.DoesNotContain("k2", e.TextoAuditoria());
    }

    [Fact]
    public async Task NoSalta400()
    {
        var cfg = new Dictionary<string, string?> { ["LLM_RESPALDO_1_API_KEY"] = "k1" };
        using var e = new EntornoAuditoria(null, cfg);
        e.Proveedor.Responde(HttpStatusCode.BadRequest, "x");
        var (c, _) = await e.Preguntar("hola", "estudiante", "T-E1");
        Assert.Equal(HttpStatusCode.ServiceUnavailable, c);
        Assert.Equal(1, e.Proveedor.Cuenta);
        var l = await e.UnaLinea();
        Assert.Equal(System.Text.Json.JsonValueKind.Null, l.GetProperty("proveedor").ValueKind);
    }

    [Fact]
    public void ArranqueInvalido()
    {
        var ex = Assert.ThrowsAny<Exception>(() => { using var e = new EntornoAuditoria(null, new Dictionary<string, string?>
            { ["LLM_RESPALDO_2_API_KEY"] = "k2", ["LLM_RESPALDO_2_PRECIO_ENTRADA_MTOK"] = "abc" }); });
        Assert.Contains("LLM_RESPALDO_2_PRECIO_ENTRADA_MTOK", ex.ToString());
    }
